BEGIN;ALTER TABLE earnings_ledger ADD COLUMN IF NOT EXISTS platform_fee_cents integer NOT NULL DEFAULT 0 CHECK(platform_fee_cents>=0),ADD COLUMN IF NOT EXISTS processor_fee_cents integer NOT NULL DEFAULT 0 CHECK(processor_fee_cents>=0),ADD COLUMN IF NOT EXISTS payout_reference text,ADD COLUMN IF NOT EXISTS paid_at timestamptz;CREATE TABLE IF NOT EXISTS payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES work_assignments(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN('authorized','captured','failed','refunded','chargeback','payout_sent','payout_paid','payout_failed')),amount_cents integer NOT NULL CHECK(amount_cents>=0),provider_reference text,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));ALTER TABLE payment_events ENABLE ROW LEVEL SECURITY;ALTER TABLE payment_events FORCE ROW LEVEL SECURITY;CREATE POLICY payment_events_tenant_isolation ON payment_events USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON payment_events TO app_runtime;COMMIT;
